  private static JWTToken parseToken(String jwt) {
    var token = jwt.split("\\.");	//fqn: java.lang.String.split
    var builder = JWTToken.builder().encoded(jwt);	//fqn: JWTToken.builder

    if (token.length >= 2) {
      var header = new String(Base64.getUrlDecoder().decode(token[0]), UTF_8);	//fqn: java.util.Base64.getUrlDecoder
      var payloadAsString = new String(Base64.getUrlDecoder().decode(token[1]), UTF_8);	//fqn: java.util.Base64.getUrlDecoder
      var headers = parse(header);
      var payload = parse(payloadAsString);
      builder.header(write(header, headers));	//fqn: builder.header
      builder.payload(write(payloadAsString, payload));	//fqn: builder.payload
      builder.validHeader(!headers.isEmpty());	//fqn: java.util.Map.isEmpty
      builder.validPayload(!payload.isEmpty());	//fqn: java.util.Map.isEmpty
      builder.validToken(!headers.isEmpty() && !payload.isEmpty());	//fqn: builder.validToken
    } else {
      builder.validToken(false);	//fqn: builder.validToken
    }
    return builder.build();	//fqn: builder.build
  }


